input.command:
python3 - <<'EOF'
import subprocess,difflib
for f,ls in [("review-triage/tools/lineorigin/README.md",[115]),("review-triage/tools/triagecheck/README.md",[14,60])]:
    old=subprocess.run(["git","show","HEAD:"+f],capture_output=True,text=True).stdout.splitlines()
    new=open(f).read().splitlines()
    for l in ls:
        a,b=old[l-1],new[l-1]
        sm=difflib.SequenceMatcher(None,a,b)
        for op,i1,i2,j1,j2 in sm.get_opcodes():
            if op!="equal": print(f,l,repr(a[max(0,i1-40):i2+40]),"=>",repr(b[max(0,j1-40):j2+40]))
EOF

