import sys,re
added={};f=None
for l in sys.stdin:
    if l.startswith('+++ '): f=l[6:].strip()
    elif l.startswith('@@'):
        m=re.search(r'\+(\d+)(?:,(\d+))?',l); s=int(m.group(1)); c=int(m.group(2) or 1)
        added.setdefault(f,set()).update(range(s,s+c))
for f,ls in added.items():
    if f=='/dev/null': continue
    L=open(f).read().split('\n')
    # build text with line mapping, strip comment markers
    txt='';pos=[]
    for i,x in enumerate(L,1):
        y=re.sub(r'^\s*(//|#)\s?','',x)
        txt+=y; pos+= [i]*len(y)
    start=0
    for m in re.finditer('。',txt):
        sent=txt[start:m.end()]; lines=set(pos[start:m.end()])
        if len(re.findall('ので',sent))>=2 and lines&ls:
            print(f, sorted(lines)[0], sent[:200])
        start=m.end()
"

