	stderr := captureStderr(t, func() {
//
// 見るのは定数であって可変の summaryCommand ではない。変数は run が書き換える
// ので、先行するテストが残した値をデフォルトと取り違えて、デフォルトの回帰を検出できない
// (または偽陽性で落ちる) ことがある。
func TestSummaryCommandDefaultIsGeneric(t *testing.T) {
// 次の 3 つは、テストがエラーの種類を文言の部分一致ではなく errors.Is で
// 識別できるようにするための番兵。文言で見ると、挙動を変えないメッセージの
// 書き換えでテストが落ちる一方、別の検査が代わりに立てたエラーの文言に
// 同じ語が含まれていると、検査が失われたことに気づけない。
